new file mode 100644
index 0000000..542b95e
--- /dev/null
+++ b/lib/doctor/contract.mjs
@@ -0,0 +1,127 @@
+// The doctor's contract, in code. `contract.md` is the same contract in prose, plus the
+// divergence table against the-boss's shape and the adapter mapping.
+//
+// This is the MINI's contract, not a mirror of the-boss's: its DoctorCheckRegistry is
+// exhaustive over a closed DoctorCheckId union, so a mini check cannot be registered
+// there and the mini cannot emit its outcome type. The-boss spawns scripts/doctor.mjs
+// and maps these JSON lines instead.
+//
+// Every function returns an ARRAY OF HUMAN-READABLE FAILURES, empty when conformant —
+// never a boolean. A gate that answers only yes/no cannot say what is wrong, and a
+// caller cannot tell "conformant" from "did not look".
+
+const ID = /^mini-[a-z0-9-]+$/;
+const STATUSES = ['pass', 'warn', 'fail', 'skip'];
+const FIX_STATUSES = ['fixed', 'requires_relaunch', 'refused'];
+
+const isText = (v) => typeof v === 'string' && v.trim() !== '';
+
+/** Failures in one outcome from a check's `run`. */
+export function outcomeConformance(outcome, where = 'outcome') {
+  const found = [];
+  if (typeof outcome !== 'object' || outcome === null) return [`${where}: not an object`];
+
+  if (!STATUSES.includes(outcome.status)) {
+    found.push(`${where}: status ${JSON.stringify(outcome.status)} is not one of ${STATUSES.join(', ')}`);
+  }
+  if (!isText(outcome.summary)) {
+    found.push(`${where}: summary ${JSON.stringify(outcome.summary)} must be a non-empty string`);
+  }
+  if (outcome.detail !== undefined && typeof outcome.detail !== 'string') {
+    found.push(`${where}: detail must be a string when present`);
+  }
+  if (outcome.actions !== undefined) {
+    if (!Array.isArray(outcome.actions)) {
+      found.push(`${where}: actions must be an array when present`);
+    } else {
+      for (const [i, action] of outcome.actions.entries()) {
+        if (action?.kind !== 'fix' || !isText(action.fixId)) {
+          found.push(`${where}: actions[${i}] must be { kind: 'fix', fixId: <non-empty string> }`);
+        }
+      }
+    }
+  }
+  return found;
+}
+
+/** Failures in one fix result. */
+export function fixOutcomeConformance(outcome, where = 'fix outcome') {
+  const found = [];
+  if (typeof outcome !== 'object' || outcome === null) return [`${where}: not an object`];
+
+  if (!FIX_STATUSES.includes(outcome.status)) {
+    // 'failed' is deliberately absent: it is the-boss's status, which its adapter
+    // produces from our 'refused'. Accepting it here would blur the two contracts.
+    found.push(`${where}: status ${JSON.stringify(outcome.status)} is not one of ${FIX_STATUSES.join(', ')}`);
+  }
+  if (!isText(outcome.summary)) {
+    found.push(`${where}: summary ${JSON.stringify(outcome.summary)} must be a non-empty string`);
+  }
+  return found;
+}
+
+/**
+ * Failures in one check's static shape. `offers` lists the fix ids the check may put in an
+ * outcome's `actions`; static validation cannot see inside `run`, so the check declares them
+ * and this pairs the declaration against `fixes`.
+ */
+export function checkConformance(check, where = null) {
+  const found = [];
+  if (typeof check !== 'object' || check === null) return ['check: not an object'];
+
+  const label = where ?? (isText(check.id) ? check.id : '(unnamed check)');
+
+  if (typeof check.id !== 'string' || !ID.test(check.id)) {
+    found.push(`${label}: id ${JSON.stringify(check.id)} must match ${ID}`);
+  }
+  if (!isText(check.title)) {
+    found.push(`${label}: title ${JSON.stringify(check.title)} must be a non-empty string`);
+  }
+  if (typeof check.run !== 'function') {
+    found.push(`${label}: run must be a function`);
+  }
+
+  const offers = check.offers ?? [];
+  const fixes = check.fixes ?? {};
+  if (!Array.isArray(offers)) {
+    found.push(`${label}: offers must be an array when present`);
+    return found;
+  }
+  if (typeof fixes !== 'object' || fixes === null) {
+    found.push(`${label}: fixes must be an object when present`);
+    return found;
+  }
+
+  for (const fixId of offers) {
+    if (typeof fixes[fixId] !== 'function') {
+      found.push(`${label}: offers ${JSON.stringify(fixId)} but fixes does not implement it`);
+    }
+  }
+  for (const fixId of Object.keys(fixes)) {
+    if (!offers.includes(fixId)) {
+      found.push(`${label}: implements fix ${JSON.stringify(fixId)} that no outcome can offer`);
+    }
+  }
+  return found;
+}
+
+/** Failures across the whole registered set, including duplicate ids. */
+export function registryConformance(checks) {
+  if (!Array.isArray(checks)) return ['registry: not an array'];
+  // An empty registry would satisfy every per-check rule vacuously, so a conformance
+  // report over it would say "all checks conform" having examined none. The doctor's
+  // whole job is to not do that.
+  if (checks.length === 0) return ['registry: empty — no checks are registered'];
+
+  const found = [];
+  const seen = new Set();
+  for (const [i, check] of checks.entries()) {
+    found.push(...checkConformance(check, isText(check?.id) ? check.id : `check[${i}]`));
+
+    if (isText(check?.id)) {
+      if (seen.has(check.id)) found.push(`${check.id}: duplicate id`);
+      seen.add(check.id);
+    }
+  }
+  return found;
+}
diff --git a/lib/doctor/contract.test.mjs b/lib/doctor/contract.test.mjs
new file mode 100644
index 0000000..9c32f4a
--- /dev/null
+++ b/lib/doctor/contract.test.mjs
@@ -0,0 +1,145 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { checkConformance, registryConformance } from './contract.mjs';
+import { allChecks } from './registry.mjs';
+
+// The conformance function is the contract in code. `lib/doctor/contract.md` is the
+// contract in prose, including the divergence table against the-boss's shape and the
+// adapter mapping — a mini check cannot be registered in the-boss's closed
+// DoctorCheckRegistry, so this is our own contract, not a mirror of one.
+
+const ok = () => ({
+  id: 'mini-example',
+  title: 'Example',
+  async run() {
+    return { status: 'pass', summary: 'fine' };
+  },
+});
+
+test('a well-formed check conforms', () => {
+  assert.deepEqual(checkConformance(ok()), []);
+});
+
+test('a check must have a mini- id of lowercase letters, digits and hyphens', () => {
+  for (const id of ['', 'example', 'boss-example', 'mini_example', 'mini-Example', 'mini.example', 42]) {
+    const found = checkConformance({ ...ok(), id });
+    assert.ok(
+      found.some((f) => /\bid\b/.test(f)),
+      `${JSON.stringify(id)} should be rejected, got ${JSON.stringify(found)}`,
+    );
+  }
+});
+
+test('a check must have a non-empty title', () => {
+  for (const title of ['', '   ', undefined, 7]) {
+    const found = checkConformance({ ...ok(), title });
+    assert.ok(
+      found.some((f) => /\btitle\b/.test(f)),
+      `${JSON.stringify(title)} should be rejected`,
+    );
+  }
+});
+
+test('a check must have a run function', () => {
+  const found = checkConformance({ id: 'mini-example', title: 'Example' });
+  assert.ok(found.some((f) => /\brun\b/.test(f)), JSON.stringify(found));
+});
+
+// The outcome rules. These are checked against a RESULT, because run() is async and the
+// registry is validated statically; scripts/doctor.mjs validates each outcome as it comes.
+test('an outcome must carry one of the four statuses and a non-empty summary', async () => {
+  const { outcomeConformance } = await import('./contract.mjs');
+
+  assert.deepEqual(outcomeConformance({ status: 'pass', summary: 'fine' }), []);
+
+  for (const status of ['ok', 'PASS', 'error', '', undefined, null]) {
+    const found = outcomeConformance({ status, summary: 'x' });
+    assert.ok(
+      found.some((f) => /\bstatus\b/.test(f)),
+      `${JSON.stringify(status)} should be rejected`,
+    );
+  }
+
+  for (const summary of ['', '  ', undefined, 3]) {
+    const found = outcomeConformance({ status: 'pass', summary });
+    assert.ok(
+      found.some((f) => /\bsummary\b/.test(f)),
+      `${JSON.stringify(summary)} should be rejected`,
+    );
+  }
+});
+
+// A status is never coerced to a default: an unknown status must surface as a conformance
+// failure. Silently treating it as 'pass' would be the vacuous-pass class — a doctor that
+// reports health it never established.
+test('an unknown status is a failure, never coerced to pass', async () => {
+  const { outcomeConformance } = await import('./contract.mjs');
+  const found = outcomeConformance({ status: 'healthy', summary: 'all good' });
+
+  assert.ok(found.length > 0);
+  assert.match(found[0], /healthy/);
+});
+
+test('a declared fix action must name an implemented fix', () => {
+  const declaredNotImplemented = {
+    ...ok(),
+    async run() {
+      return { status: 'fail', summary: 'broken', actions: [{ kind: 'fix', fixId: 'repair' }] };
+    },
+    fixes: {},
+  };
+  // Static validation cannot see inside run(), so the registry check pairs the two by
+  // asking each check to declare its offerable fix ids.
+  const found = checkConformance({ ...declaredNotImplemented, offers: ['repair'] });
+  assert.ok(found.some((f) => /repair/.test(f)), JSON.stringify(found));
+
+  const implementedNotDeclared = {
+    ...ok(),
+    offers: [],
+    fixes: { repair: async () => ({ status: 'fixed', summary: 'done' }) },
+  };
+  const found2 = checkConformance(implementedNotDeclared);
+  assert.ok(found2.some((f) => /repair/.test(f)), JSON.stringify(found2));
+});
+
+test('a fix outcome must carry one of the three statuses and a summary', async () => {
+  const { fixOutcomeConformance } = await import('./contract.mjs');
+
+  for (const status of ['fixed', 'requires_relaunch', 'refused']) {
+    assert.deepEqual(fixOutcomeConformance({ status, summary: 'x' }), []);
+  }
+  // 'failed' is the-boss's status, not ours — the adapter maps our 'refused' onto it.
+  // Accepting it here would blur the two contracts the contract document separates.
+  for (const status of ['failed', 'ok', '', undefined]) {
+    const found = fixOutcomeConformance({ status, summary: 'x' });
+    assert.ok(found.some((f) => /\bstatus\b/.test(f)), `${JSON.stringify(status)} should be rejected`);
+  }
+});
+
+// The registry is the real subject: these assertions are what make the contract binding on
+// the shipped check set rather than on a fixture.
+test('every registered check conforms', () => {
+  const found = registryConformance(allChecks());
+  assert.deepEqual(found, [], `registered checks violate the contract:\n${found.join('\n')}`);
+});
+
+test('registered ids are unique', () => {
+  const ids = allChecks().map((c) => c.id);
+  assert.equal(new Set(ids).size, ids.length, JSON.stringify(ids));
+});
+
+test('exactly one registered check offers a fix, and it is copy-skills', () => {
+  const offering = allChecks().filter((c) => (c.offers ?? []).length > 0);
+
+  assert.deepEqual(
+    offering.map((c) => c.id),
+    ['mini-skill-copies'],
+  );
+  assert.deepEqual(offering[0].offers, ['copy-skills']);
+  assert.equal(typeof offering[0].fixes['copy-skills'], 'function');
+});
+
+test('a duplicate id in the registry is reported', () => {
+  const found = registryConformance([ok(), ok()]);
+  assert.ok(found.some((f) => /duplicate|mini-example/.test(f)), JSON.stringify(found));
+});
diff --git a/lib/doctor/kbd.mjs b/lib/doctor/kbd.mjs
new file mode 100644
index 0000000..dc443e1
--- /dev/null
+++ b/lib/doctor/kbd.mjs
@@ -0,0 +1,87 @@
+// KBD position: the canonical runtime and the on-disk projection must agree.
+//
+// CLAUDE.md §0.1: `prometheus kbd status` is canonical; `current-waypoint.json` is a
+// projection, not a source of truth. So a disagreement between them is a real finding —
+// something wrote state out of band — and is the one thing this check exists to catch.
+
+import { existsSync, readFileSync } from 'node:fs';
+import path from 'node:path';
+import { spawnExecutable } from '../platform/spawn.mjs';
+
+const repoRootDefault = () => path.resolve(new URL('../..', import.meta.url).pathname);
+
+/** The phase id, wherever this shape happens to carry it. */
+const phaseOf = (value) => {
+  if (!value || typeof value !== 'object') return null;
+  const phase = value.phase ?? value.activePhase ?? null;
+  if (typeof phase === 'string') return phase;
+  if (phase && typeof phase === 'object') return phase.id ?? phase.name ?? null;
+  return null;
+};
+
+export const checks = [
+  {
+    id: 'mini-kbd-state',
+    title: 'KBD position',
+    offers: [],
+    fixes: {},
+    async run(ctx = {}) {
+      const repoRoot = ctx.repoRoot ?? repoRootDefault();
+      const spawn = ctx.spawn ?? spawnExecutable;
+      const waypointPath = path.join(repoRoot, '.kbd-orchestrator', 'current-waypoint.json');
+
+      let canonical = null;
+      const result = spawn('prometheus', ['kbd', '--path', repoRoot, 'status', '--json']);
+      if (result?.status === 0) {
+        try {
+          canonical = phaseOf(JSON.parse(String(result.stdout ?? '')));
+        } catch {
+          canonical = null;
+        }
+      }
+
+      const hasWaypoint = existsSync(waypointPath);
+      let projected = null;
+      let waypointBroken = false;
+      if (hasWaypoint) {
+        try {
+          projected = phaseOf(JSON.parse(readFileSync(waypointPath, 'utf8')));
+        } catch {
+          waypointBroken = true;
+        }
+      }
+
+      if (waypointBroken) {
+        return {
+          status: 'fail',
+          summary: 'The waypoint projection could not be parsed',
+          detail: `${waypointPath} is not valid JSON. Nothing that reads position will work until it is.`,
+        };
+      }
+      if (canonical === null && !hasWaypoint) {
+        return {
+          status: 'skip',
+          summary: 'No KBD state here',
+          detail: 'Neither the prometheus CLI nor a waypoint projection is present; this may not be a KBD project.',
+        };
+      }
+      if (canonical === null) {
+        return {
+          status: 'warn',
+          summary: `The prometheus CLI is not available; the projection reports ${projected ?? '(no phase)'}`,
+          detail: `Canonical state could not be read, so ${waypointPath} is unverified.`,
+        };
+      }
+      if (projected !== null && projected !== canonical) {
+        return {
+          status: 'fail',
+          summary: 'Canonical KBD state and the waypoint projection disagree',
+          detail:
+            `canonical: ${canonical}\nprojection: ${projected}\n\n` +
+            `The runtime is authoritative; something wrote ${waypointPath} out of band.`,
+        };
+      }
+      return { status: 'pass', summary: `Phase ${canonical}` };
+    },
+  },
+];
diff --git a/lib/doctor/kbd.test.mjs b/lib/doctor/kbd.test.mjs
new file mode 100644
index 0000000..4fc13a6
--- /dev/null
+++ b/lib/doctor/kbd.test.mjs
@@ -0,0 +1,94 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
+import path from 'node:path';
+import { tempDir } from '../platform/paths.mjs';
+import { outcomeConformance, checkConformance } from './contract.mjs';
+import { checks } from './kbd.mjs';
+
+const check = checks.find((c) => c.id === 'mini-kbd-state');
+assert.ok(check, 'mini-kbd-state must exist');
+
+const run = async (ctx) => {
+  const outcome = await check.run(ctx);
+  assert.deepEqual(outcomeConformance(outcome, check.id), [], JSON.stringify(outcome));
+  return outcome;
+};
+
+const repo = (waypoint) => {
+  const root = mkdtempSync(path.join(tempDir(), 'doctor-kbd-'));
+  if (waypoint !== undefined) {
+    mkdirSync(path.join(root, '.kbd-orchestrator'), { recursive: true });
+    writeFileSync(path.join(root, '.kbd-orchestrator', 'current-waypoint.json'), waypoint);
+  }
+  return { root, dispose: () => rmSync(root, { recursive: true, force: true }) };
+};
+
+const cli = (payload) => () => ({ status: 0, stdout: JSON.stringify(payload), stderr: '' });
+const noCli = () => () => ({ status: 127, stdout: '', stderr: 'command not found' });
+
+test('the CLI and the projection agreeing is a pass', async () => {
+  const r = repo(JSON.stringify({ phase: 'karpathy-logs-node' }));
+  try {
+    const outcome = await run({ repoRoot: r.root, spawn: cli({ phase: { id: 'karpathy-logs-node' } }) });
+
+    assert.equal(outcome.status, 'pass');
+    assert.match(outcome.summary, /karpathy-logs-node/);
+  } finally {
+    r.dispose();
+  }
+});
+
+// The canonical runtime is the source of truth and the waypoint is a projection. When they
+// disagree, something has written state out of band — exactly what the spec forbids.
+test('the CLI and the projection disagreeing is a failure, naming both', async () => {
+  const r = repo(JSON.stringify({ phase: 'stale-phase' }));
+  try {
+    const outcome = await run({ repoRoot: r.root, spawn: cli({ phase: { id: 'karpathy-logs-node' } }) });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.detail, /stale-phase/);
+    assert.match(outcome.detail, /karpathy-logs-node/);
+  } finally {
+    r.dispose();
+  }
+});
+
+test('no CLI but a parseable projection is a warning, not a failure', async () => {
+  const r = repo(JSON.stringify({ phase: 'karpathy-logs-node' }));
+  try {
+    const outcome = await run({ repoRoot: r.root, spawn: noCli() });
+
+    assert.equal(outcome.status, 'warn');
+    assert.match(outcome.summary + outcome.detail, /karpathy-logs-node/);
+  } finally {
+    r.dispose();
+  }
+});
+
+test('an unparseable projection is a failure that names the file', async () => {
+  const r = repo('{ not json');
+  try {
+    const outcome = await run({ repoRoot: r.root, spawn: noCli() });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.summary + outcome.detail, /current-waypoint\.json/);
+  } finally {
+    r.dispose();
+  }
+});
+
+test('neither present is a skip: this may simply not be a KBD project', async () => {
+  const r = repo(undefined);
+  try {
+    const outcome = await run({ repoRoot: r.root, spawn: noCli() });
+
+    assert.equal(outcome.status, 'skip');
+  } finally {
+    r.dispose();
+  }
+});
+
+test('the check satisfies the contract statically', () => {
+  for (const c of checks) assert.deepEqual(checkConformance(c), [], c.id);
+});
diff --git a/lib/doctor/registry.mjs b/lib/doctor/registry.mjs
