--- /dev/null
+++ b/lib/doctor/registry.mjs
@@ -0,0 +1,18 @@
+// The registered check set, in report order: the cheapest and most fundamental first, so
+// a terminal reader sees the runtime verdict before the network probes, and the binding
+// install-scope rule last where it cannot be missed.
+//
+// Each group module exports `checks: []`. The contract test binds on whatever is
+// registered here, so a check that ships is a check that conforms.
+
+import { checks as runtime } from './runtime.mjs';
+import { checks as tools } from './tools.mjs';
+import { checks as services } from './services.mjs';
+import { checks as skills } from './skills.mjs';
+import { checks as kbd } from './kbd.mjs';
+import { checks as scope } from './scope.mjs';
+
+/** Every registered check, in report order. */
+export function allChecks() {
+  return [...runtime, ...tools, ...services, ...skills, ...kbd, ...scope];
+}
diff --git a/lib/doctor/runtime.mjs b/lib/doctor/runtime.mjs
new file mode 100644
index 0000000..30bc928
--- /dev/null
+++ b/lib/doctor/runtime.mjs
@@ -0,0 +1,151 @@
+// Runtime checks: the Node floor, the version authority, and the submodule checkouts.
+// Nothing here touches the network or a service, so this group runs everywhere and is
+// the first thing a terminal reader sees.
+//
+// Every effect arrives through `ctx` so the tests run against fixtures rather than this
+// machine. The defaults are the real readers.
+
+import { existsSync, readFileSync, readdirSync } from 'node:fs';
+import path from 'node:path';
+import { spawnExecutable } from '../platform/spawn.mjs';
+import { compareToTree, parseVersionsToml } from '../../rules/lib/versions-toml.mjs';
+
+const NODE_FLOOR = 22;
+
+const repoRootDefault = () => path.resolve(new URL('../..', import.meta.url).pathname);
+
+/** The gitlink commit at `p` in HEAD, or null; throws when git itself cannot be read. */
+const lsTreeDefault = (repoRoot) => (p) => {
+  const result = spawnExecutable('git', ['ls-tree', 'HEAD', '--', p], { cwd: repoRoot });
+  if (result.status !== 0) throw new Error(`git ls-tree failed: ${(result.stderr ?? '').trim()}`);
+  const match = /^160000 commit ([0-9a-f]{40})\t/.exec((result.stdout ?? '').trim());
+  return match ? match[1] : null;
+};
+
+/** Every gitlink path in HEAD; throws when git cannot be read, never reports an empty tree. */
+const listGitlinksDefault = (repoRoot) => () => {
+  const result = spawnExecutable('git', ['ls-tree', '-r', 'HEAD'], { cwd: repoRoot });
+  if (result.status !== 0) throw new Error(`git ls-tree failed: ${(result.stderr ?? '').trim()}`);
+  return (result.stdout ?? '')
+    .split('\n')
+    .map((line) => /^160000 commit [0-9a-f]{40}\t(.+)$/.exec(line))
+    .filter(Boolean)
+    .map((match) => match[1]);
+};
+
+export const checks = [
+  {
+    id: 'mini-node-version',
+    title: 'Node.js version',
+    offers: [],
+    fixes: {},
+    async run({ nodeVersion = process.versions.node } = {}) {
+      // Numeric: '9.0.0' sorts above '22.0.0' as a string, so a lexical compare would
+      // pass a runtime four majors too old.
+      const major = Number.parseInt(String(nodeVersion).split('.')[0], 10);
+
+      if (!Number.isFinite(major)) {
+        return { status: 'fail', summary: `Could not read the Node version from ${JSON.stringify(nodeVersion)}` };
+      }
+      if (major < NODE_FLOOR) {
+        return {
+          status: 'fail',
+          summary: `Node ${nodeVersion} is below the floor of ${NODE_FLOOR}`,
+          detail: `This pack targets Node LTS >= ${NODE_FLOOR}. Install a supported runtime and re-run.`,
+        };
+      }
+      return { status: 'pass', summary: `Node ${nodeVersion}` };
+    },
+  },
+
+  {
+    id: 'mini-versions-toml',
+    title: 'Version authority',
+    offers: [],
+    fixes: {},
+    async run(ctx = {}) {
+      const repoRoot = ctx.repoRoot ?? repoRootDefault();
+      const versionsToml = path.join(repoRoot, 'versions.toml');
+
+      if (!existsSync(versionsToml)) {
+        return {
+          status: 'skip',
+          summary: 'versions.toml has not been authored yet',
+          detail: `Expected at ${versionsToml}. The operator writes it; agents never do. See docs/versions-toml.md.`,
+        };
+      }
+
+      let disagreements;
+      try {
+        const parsed = parseVersionsToml(readFileSync(versionsToml, 'utf8'));
+        const packageJson = JSON.parse(readFileSync(path.join(repoRoot, 'package.json'), 'utf8'));
+        disagreements = compareToTree(parsed, {
+          lsTree: ctx.lsTree ?? lsTreeDefault(repoRoot),
+          listGitlinks: ctx.listGitlinks ?? listGitlinksDefault(repoRoot),
+          packageJson,
+        });
+      } catch (error) {
+        // A file the operator wrote that will not parse is a finding about the file,
+        // not a crash of the doctor.
+        return {
+          status: 'fail',
+          summary: 'versions.toml could not be read',
+          detail: String(error?.message ?? error),
+        };
+      }
+
+      if (disagreements.length > 0) {
+        return {
+          status: 'fail',
+          summary: `versions.toml disagrees with the tree in ${disagreements.length} place(s)`,
+          detail: disagreements.join('\n'),
+        };
+      }
+      return { status: 'pass', summary: 'versions.toml agrees with the tree' };
+    },
+  },
+
+  {
+    id: 'mini-submodules',
+    title: 'Submodule checkouts',
+    offers: [],
+    fixes: {},
+    async run(ctx = {}) {
+      const repoRoot = ctx.repoRoot ?? repoRootDefault();
+
+      let gitlinks;
+      try {
+        gitlinks = (ctx.listGitlinks ?? listGitlinksDefault(repoRoot))();
+      } catch (error) {
+        // Reporting "no submodules" here would be a pass over an unread tree.
+        return {
+          status: 'skip',
+          summary: 'git could not be read, so submodules were not checked',
+          detail: String(error?.message ?? error),
+        };
+      }
+
+      const empty = gitlinks.filter((p) => {
+        const dir = path.join(repoRoot, p);
+        try {
+          return readdirSync(dir).length === 0;
+        } catch {
+          return true; // absent entirely
+        }
+      });
+
+      if (empty.length > 0) {
+        return {
+          status: 'fail',
+          summary: `${empty.length} of ${gitlinks.length} submodule(s) are not checked out`,
+          detail: `${empty.join('\n')}\n\nRun: git submodule update --init --recursive`,
+        };
+      }
+      return {
+        status: 'pass',
+        summary:
+          gitlinks.length === 0 ? 'No submodules are pinned' : `${gitlinks.length} submodule(s) are checked out`,
+      };
+    },
+  },
+];
diff --git a/lib/doctor/runtime.test.mjs b/lib/doctor/runtime.test.mjs
new file mode 100644
index 0000000..8b05571
--- /dev/null
+++ b/lib/doctor/runtime.test.mjs
@@ -0,0 +1,183 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
+import path from 'node:path';
+import { tempDir } from '../platform/paths.mjs';
+import { outcomeConformance } from './contract.mjs';
+import { checks } from './runtime.mjs';
+
+const byId = (id) => {
+  const check = checks.find((c) => c.id === id);
+  assert.ok(check, `no check ${id}`);
+  return check;
+};
+
+/** Asserts the shape as well as the verdict: an outcome off-contract is a defect even when its status is right. */
+const run = async (check, ctx) => {
+  const outcome = await check.run(ctx);
+  assert.deepEqual(outcomeConformance(outcome, check.id), [], JSON.stringify(outcome));
+  return outcome;
+};
+
+const repo = (build) => {
+  const root = mkdtempSync(path.join(tempDir(), 'doctor-runtime-'));
+  try {
+    build?.(root);
+    return { root, dispose: () => rmSync(root, { recursive: true, force: true }) };
+  } catch (error) {
+    rmSync(root, { recursive: true, force: true });
+    throw error;
+  }
+};
+
+test('mini-node-version passes on a supported runtime and names the version', async () => {
+  const outcome = await run(byId('mini-node-version'), { nodeVersion: '24.16.0' });
+
+  assert.equal(outcome.status, 'pass');
+  assert.match(outcome.summary, /24\.16\.0/);
+});
+
+test('mini-node-version fails below the floor, naming both versions', async () => {
+  const outcome = await run(byId('mini-node-version'), { nodeVersion: '20.0.0' });
+
+  assert.equal(outcome.status, 'fail');
+  assert.match(outcome.summary, /20\.0\.0/);
+  assert.match(outcome.summary, /22/);
+});
+
+test('mini-node-version compares numerically, not lexically', async () => {
+  // '9.0.0' > '22.0.0' as strings; the floor is a number comparison or it is wrong.
+  assert.equal((await run(byId('mini-node-version'), { nodeVersion: '9.0.0' })).status, 'fail');
+  assert.equal((await run(byId('mini-node-version'), { nodeVersion: '22.0.0' })).status, 'pass');
+  assert.equal((await run(byId('mini-node-version'), { nodeVersion: '100.0.0' })).status, 'pass');
+});
+
+test('mini-versions-toml skips with a reason when the file is absent', async () => {
+  const { root, dispose } = repo();
+  try {
+    const outcome = await run(byId('mini-versions-toml'), { repoRoot: root });
+
+    assert.equal(outcome.status, 'skip');
+    assert.match(outcome.summary, /versions\.toml/);
+  } finally {
+    dispose();
+  }
+});
+
+test('mini-versions-toml passes when the file agrees with the tree', async () => {
+  const { root, dispose } = repo((r) => {
+    writeFileSync(path.join(r, 'versions.toml'), '[node]\nminimum = ">=22"\n');
+    writeFileSync(path.join(r, 'package.json'), JSON.stringify({ engines: { node: '>=22' } }));
+  });
+  try {
+    const outcome = await run(byId('mini-versions-toml'), {
+      repoRoot: root,
+      lsTree: () => null,
+      listGitlinks: () => [],
+    });
+
+    assert.equal(outcome.status, 'pass');
+  } finally {
+    dispose();
+  }
+});
+
+test('mini-versions-toml fails naming each disagreement', async () => {
+  const { root, dispose } = repo((r) => {
+    writeFileSync(path.join(r, 'versions.toml'), '[node]\nminimum = ">=22"\n[submodules]\n"tools/x" = "aaaaaaa"\n');
+    writeFileSync(path.join(r, 'package.json'), JSON.stringify({ engines: { node: '>=24' } }));
+  });
+  try {
+    const outcome = await run(byId('mini-versions-toml'), {
+      repoRoot: root,
+      lsTree: () => null,
+      listGitlinks: () => [],
+    });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.detail, /tools\/x/);
+    assert.match(outcome.detail, /engines\.node|>=24/);
+  } finally {
+    dispose();
+  }
+});
+
+// A parse error is a real finding about a file the operator wrote, not a crash.
+test('mini-versions-toml reports an unparseable file as fail, not an exception', async () => {
+  const { root, dispose } = repo((r) => {
+    writeFileSync(path.join(r, 'versions.toml'), '[submodule]\n"tools/x" = "aaaaaaa"\n');
+    writeFileSync(path.join(r, 'package.json'), JSON.stringify({ engines: { node: '>=22' } }));
+  });
+  try {
+    const outcome = await run(byId('mini-versions-toml'), {
+      repoRoot: root,
+      lsTree: () => null,
+      listGitlinks: () => [],
+    });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.summary + outcome.detail, /unknown table|parse/i);
+  } finally {
+    dispose();
+  }
+});
+
+test('mini-submodules passes when every gitlink is checked out', async () => {
+  const { root, dispose } = repo((r) => {
+    mkdirSync(path.join(r, 'tools', 'prometheus-knowledge'), { recursive: true });
+    writeFileSync(path.join(r, 'tools', 'prometheus-knowledge', 'Cargo.toml'), '');
+  });
+  try {
+    const outcome = await run(byId('mini-submodules'), {
+      repoRoot: root,
+      listGitlinks: () => ['tools/prometheus-knowledge'],
+    });
+
+    assert.equal(outcome.status, 'pass');
+  } finally {
+    dispose();
+  }
+});
+
+// An uninitialised submodule is an empty directory — the single most common broken clone.
+test('mini-submodules fails naming an uninitialised submodule', async () => {
+  const { root, dispose } = repo((r) => {
+    mkdirSync(path.join(r, 'tools', 'prometheus-knowledge'), { recursive: true });
+  });
+  try {
+    const outcome = await run(byId('mini-submodules'), {
+      repoRoot: root,
+      listGitlinks: () => ['tools/prometheus-knowledge'],
+    });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.summary + outcome.detail, /prometheus-knowledge/);
+    assert.match(outcome.summary + outcome.detail, /submodule update|init/i);
+  } finally {
+    dispose();
+  }
+});
+
+test('mini-submodules skips when git cannot be read, rather than claiming none', async () => {
+  const { root, dispose } = repo();
+  try {
+    const outcome = await run(byId('mini-submodules'), {
+      repoRoot: root,
+      listGitlinks: () => {
+        throw new Error('git ls-tree failed');
+      },
+    });
+
+    assert.equal(outcome.status, 'skip');
+    assert.match(outcome.summary, /git/i);
+  } finally {
+    dispose();
+  }
+});
+
+test('every check in this group satisfies the contract statically', async () => {
+  const { checkConformance } = await import('./contract.mjs');
+  for (const check of checks) {
+    assert.deepEqual(checkConformance(check), [], check.id);
+  }
+});
diff --git a/lib/doctor/scope.mjs b/lib/doctor/scope.mjs
new file mode 100644
index 0000000..83fa119
--- /dev/null
+++ b/lib/doctor/scope.mjs
@@ -0,0 +1,75 @@
+// The install-scope rule, verified at runtime.
+//
+// openspec/config.yaml, binding: the mini pack is NEVER installed natively on a machine
+// that already has the full skill pack. Inside the-boss's own data directory is fine;
+// anywhere under the user's home on such a machine is not, because the two would shadow
+// each other's skills.
+//
+// This check offers NO fix. Removing a user's files is not an idempotent copy, and it is
+// not obvious which copy is authoritative — so it names what to remove and stops.
+
+import { existsSync, readdirSync } from 'node:fs';
+import path from 'node:path';
+import { detectFullPack as detectFullPackDefault } from '../platform/full-pack.mjs';
+import { homeDir } from '../platform/paths.mjs';
+
+const SKILL_ROOTS = ['.agents', '.claude'];
+
+const packRootDefault = () => path.resolve(new URL('../..', import.meta.url).pathname);
+
+const listSkillNamesDefault = (packRoot) => () => {
+  try {
+    return readdirSync(path.join(packRoot, 'skills'), { withFileTypes: true })
+      .filter((e) => e.isDirectory())
+      .map((e) => e.name);
+  } catch {
+    return [];
+  }
+};
+
+export const checks = [
+  {
+    id: 'mini-install-scope',
+    title: 'Install scope',
+    offers: [],
+    fixes: {},
+    async run(ctx = {}) {
+      const packRoot = ctx.packRoot ?? packRootDefault();
+      const home = ctx.home ?? homeDir();
+      const detect = ctx.detectFullPack ?? detectFullPackDefault;
+      const listSkillNames = ctx.listSkillNames ?? listSkillNamesDefault(packRoot);
+
+      const full = detect({ home });
+      if (!full.present) {
+        return { status: 'pass', summary: 'No full skill pack is installed here; native copies are allowed' };
+      }
+
+      const names = listSkillNames();
+      const offending = [];
+      for (const name of names) {
+        for (const root of SKILL_ROOTS) {
+          const copy = path.join(home, root, 'skills', name);
+          if (existsSync(copy)) offending.push(copy);
+        }
+      }
+
+      if (offending.length === 0) {
+        return {
+          status: 'pass',
+          summary: 'The full skill pack is installed here, and no mini copies sit beside it',
+          detail: `Markers:\n${full.markers.join('\n')}`,
+        };
+      }
+
+      return {
+        status: 'fail',
+        summary: `${offending.length} mini skill copy(ies) are installed natively beside the full skill pack`,
+        detail:
+          `The mini must never be installed natively on a machine that has the full pack ` +
+          `(openspec/config.yaml); inside the-boss's own data directory is fine. The two shadow ` +
+          `each other's skills.\n\nFull-pack markers:\n${full.markers.join('\n')}\n\n` +
+          `Remove these directories:\n${offending.join('\n')}`,
+      };
+    },
+  },
+];
