index 0000000..19fc565
--- /dev/null
+++ b/lib/doctor/services.mjs
@@ -0,0 +1,135 @@
+// The two resident services, and Docker underneath them.
+//
+// CLAUDE.md §P: everything must still work with both services down. So "not running" is a
+// WARNING with the command to start it, never a failure. A failure here means something IS
+// listening and answering wrongly — a fault, as distinct from an absence.
+
+const DEFAULT_TIMEOUT_MS = 2000;
+
+/** Probes a health endpoint, distinguishing "nothing listening" from "answered badly". */
+async function probe({ url, fetchImpl, timeoutMs }) {
+  const controller = new AbortController();
+  const timer = setTimeout(() => controller.abort(), timeoutMs);
+  try {
+    const response = await fetchImpl(url, { signal: controller.signal });
+    return { reached: true, status: response.status };
+  } catch (error) {
+    // An abort and a refused connection are both "not reachable", but they are different
+    // stories for the operator, so the reason travels with the result.
+    const aborted = error?.name === 'AbortError';
+    return {
+      reached: false,
+      aborted,
+      reason: aborted ? `timed out after ${timeoutMs}ms` : String(error?.message ?? error),
+    };
+  } finally {
+    clearTimeout(timer);
+  }
+}
+
+/**
+ * A service check. `okStatuses` are the codes that mean "up": liter-llm's /health answers
+ * 200, and a 401 from a gateway means it is up and wants a key — verified against the
+ * running services, not assumed.
+ */
+const service = ({ id, title, url, start, okStatuses = [200] }) => ({
+  id,
+  title,
+  offers: [],
+  fixes: {},
+  async run(ctx = {}) {
+    const result = await probe({
+      url,
+      fetchImpl: ctx.fetch ?? globalThis.fetch,
+      timeoutMs: ctx.timeoutMs ?? DEFAULT_TIMEOUT_MS,
+    });
+
+    if (!result.reached) {
+      return {
+        status: 'warn',
+        summary: `Not reachable at ${url}`,
+        detail: `${result.reason}\n\nThe pack works with this service down. To start it: ${start}`,
+      };
+    }
+    if (!okStatuses.includes(result.status)) {
+      return {
+        status: 'fail',
+        summary: `${url} answered ${result.status}`,
+        detail: `Something is listening but not healthy. Expected ${okStatuses.join(' or ')}.`,
+      };
+    }
+    return {
+      status: 'pass',
+      summary:
+        result.status === 401
+          ? `Up at ${url} (401: the gateway is running and requires a key)`
+          : `Up at ${url}`,
+    };
+  },
+});
+
+export const checks = [
+  {
+    id: 'mini-docker',
+    title: 'Docker',
+    offers: [],
+    fixes: {},
+    async run(ctx = {}) {
+      // lib/platform/docker.mjs is created by change `docker-services`. Until then this
+      // must skip: passing would report a verdict it never reached, and failing would
+      // make an unbuilt dependency look like a broken machine.
+      const load =
+        ctx.loadDocker ??
+        (async () => {
+          try {
+            return await import('../platform/docker.mjs');
+          } catch {
+            return null;
+          }
+        });
+
+      const docker = await load();
+      if (!docker || typeof docker.detectDocker !== 'function') {
+        return {
+          status: 'skip',
+          summary: 'Docker detection is not available yet',
+          detail: 'lib/platform/docker.mjs is created by change `docker-services`; this check runs once it lands.',
+        };
+      }
+
+      const found = docker.detectDocker();
+      if (found.state === 'running') {
+        return { status: 'pass', summary: `Docker ${found.version ?? ''}`.trim() };
+      }
+      if (found.state === 'absent') {
+        return {
+          status: 'warn',
+          summary: 'Docker is not installed',
+          detail: 'The two services need it. Install Docker Desktop (Windows/macOS) or the engine (Linux).',
+        };
+      }
+      return {
+        status: 'fail',
+        summary: 'Docker is installed but its daemon is not running',
+        detail: found.detail ?? 'Start Docker and re-run.',
+      };
+    },
+  },
+
+  service({
+    id: 'mini-service-surreal-memory',
+    title: 'surreal-memory',
+    url: 'http://localhost:8000/health',
+    start: 'node scripts/services.mjs up surreal-memory',
+  }),
+
+  service({
+    id: 'mini-service-liter-llm',
+    title: 'liter-llm gateway',
+    url: 'http://localhost:4000/health',
+    start: 'node scripts/services.mjs up liter-llm',
+    // 401 means up-and-requires-a-key, which is this gateway's documented posture;
+    // verified against the running service (/health → 200, /v1/models → 401).
+    okStatuses: [200, 401],
+  }),
+];
diff --git a/lib/doctor/services.test.mjs b/lib/doctor/services.test.mjs
new file mode 100644
index 0000000..a71a502
--- /dev/null
+++ b/lib/doctor/services.test.mjs
@@ -0,0 +1,115 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { outcomeConformance, checkConformance } from './contract.mjs';
+import { checks } from './services.mjs';
+
+const byId = (id) => {
+  const check = checks.find((c) => c.id === id);
+  assert.ok(check, `no check ${id}`);
+  return check;
+};
+
+const run = async (id, ctx) => {
+  const outcome = await byId(id).run(ctx);
+  assert.deepEqual(outcomeConformance(outcome, id), [], JSON.stringify(outcome));
+  return outcome;
+};
+
+const ok = (body = {}) => async () => ({ ok: true, status: 200, json: async () => body, text: async () => '' });
+const status = (code) => async () => ({ ok: code < 400, status: code, json: async () => ({}), text: async () => '' });
+const unreachable = () => async () => {
+  throw Object.assign(new Error('connect ECONNREFUSED 127.0.0.1:8000'), { code: 'ECONNREFUSED' });
+};
+
+// `lib/platform/docker.mjs` is created by change `docker-services`. Until it lands this
+// check must SKIP with the reason — never pass, which would report a Docker verdict it
+// never reached, and never fail, which would make a not-yet-built dependency look broken.
+test('mini-docker skips when the platform module is absent', async () => {
+  const outcome = await run('mini-docker', { loadDocker: async () => null });
+
+  assert.equal(outcome.status, 'skip');
+  assert.match(outcome.summary + outcome.detail, /docker-services|not.*(yet|available)|absent/i);
+});
+
+test('mini-docker warns, not fails, when Docker is simply not installed', async () => {
+  const outcome = await run('mini-docker', {
+    loadDocker: async () => ({ detectDocker: () => ({ state: 'absent' }) }),
+  });
+
+  assert.equal(outcome.status, 'warn');
+  assert.match(outcome.summary + outcome.detail, /docker/i);
+});
+
+test('mini-docker fails when Docker is installed but its daemon is unreachable', async () => {
+  const outcome = await run('mini-docker', {
+    loadDocker: async () => ({
+      detectDocker: () => ({ state: 'installed-not-running', detail: 'Cannot connect to the Docker daemon' }),
+    }),
+  });
+
+  assert.equal(outcome.status, 'fail');
+  assert.match(outcome.summary + outcome.detail, /daemon|running/i);
+});
+
+test('mini-docker passes when the daemon answers', async () => {
+  const outcome = await run('mini-docker', {
+    loadDocker: async () => ({ detectDocker: () => ({ state: 'running', version: '27.1.1' }) }),
+  });
+
+  assert.equal(outcome.status, 'pass');
+  assert.match(outcome.summary, /27\.1\.1/);
+});
+
+for (const [id, url] of [
+  ['mini-service-surreal-memory', 'http://localhost:8000'],
+  ['mini-service-liter-llm', 'http://localhost:4000'],
+]) {
+  test(`${id} passes when its health endpoint answers 200`, async () => {
+    const outcome = await run(id, { fetch: ok() });
+
+    assert.equal(outcome.status, 'pass');
+  });
+
+  // Everything must still work with both services down: absent is a warning, not a failure.
+  test(`${id} warns when nothing is listening`, async () => {
+    const outcome = await run(id, { fetch: unreachable() });
+
+    assert.equal(outcome.status, 'warn');
+    assert.match(outcome.summary + outcome.detail, new RegExp(url.replace(/[.:/]/g, '\\$&')));
+  });
+
+  // Something IS listening and answering wrongly — that is a real fault, not an absence.
+  test(`${id} fails when the endpoint answers non-200`, async () => {
+    const outcome = await run(id, { fetch: status(500) });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.summary + outcome.detail, /500/);
+  });
+
+  test(`${id} does not hang forever on a silent socket`, async () => {
+    const outcome = await run(id, {
+      fetch: async (_url, { signal } = {}) => {
+        // Mimic fetch's behaviour when the caller's AbortSignal fires.
+        if (signal?.aborted) throw Object.assign(new Error('aborted'), { name: 'AbortError' });
+        throw Object.assign(new Error('The operation was aborted'), { name: 'AbortError' });
+      },
+      timeoutMs: 1,
+    });
+
+    assert.equal(outcome.status, 'warn');
+    assert.match(outcome.summary + outcome.detail, /timed out|abort/i);
+  });
+}
+
+// A 401 means the gateway is up and requires a key — which is liter-llm's documented
+// posture, not a fault of the service.
+test('mini-service-liter-llm treats 401 as up-and-authenticated, not broken', async () => {
+  const outcome = await run('mini-service-liter-llm', { fetch: status(401) });
+
+  assert.equal(outcome.status, 'pass');
+  assert.match(outcome.summary + (outcome.detail ?? ''), /401|key|auth/i);
+});
+
+test('every check in this group satisfies the contract statically', () => {
+  for (const check of checks) assert.deepEqual(checkConformance(check), [], check.id);
+});
diff --git a/lib/doctor/skills.mjs b/lib/doctor/skills.mjs
new file mode 100644
index 0000000..20e75fa
--- /dev/null
+++ b/lib/doctor/skills.mjs
@@ -0,0 +1,174 @@
+// The home-directory skill copies: the pack's skills must also live under
+// <home>/.agents/skills/<name> and <home>/.claude/skills/<name>, so tools that are not
+// the-boss can find them.
+//
+// A-3, the one real trust boundary in this change: `copy-skills` WRITES UNDER THE USER'S
+// HOME. It therefore writes only to those two roots, only for names the pack actually
+// has, refuses any name that is not a single plain directory component, never deletes,
+// and refuses outright on a machine that already has the full pack (openspec/config.yaml
+// — the two must never shadow each other's skills).
+
+import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
+import path from 'node:path';
+import { atomicWrite } from '../platform/atomic-write.mjs';
+import { detectFullPack as detectFullPackDefault } from '../platform/full-pack.mjs';
+import { homeDir } from '../platform/paths.mjs';
+
+const SKILL_ROOTS = ['.agents', '.claude'];
+
+const packRootDefault = () => path.resolve(new URL('../..', import.meta.url).pathname);
+
+/**
+ * A skill name must be ONE plain directory component: no separator, no `..`, no drive,
+ * no absolute path. Anything else could place a write outside the two roots, which is
+ * the whole point of the boundary.
+ */
+const isSafeName = (name) =>
+  typeof name === 'string' &&
+  name !== '' &&
+  name !== '.' &&
+  name !== '..' &&
+  !name.includes('/') &&
+  !name.includes('\\') &&
+  !path.isAbsolute(name) &&
+  path.basename(name) === name;
+
+const listSkillNamesDefault = (packRoot) => () => {
+  const dir = path.join(packRoot, 'skills');
+  try {
+    return readdirSync(dir, { withFileTypes: true })
+      .filter((e) => e.isDirectory())
+      .map((e) => e.name);
+  } catch {
+    return [];
+  }
+};
+
+/** Every file in a skill, as paths relative to the skill directory. */
+const filesUnder = (dir, prefix = '') => {
+  const out = [];
+  for (const entry of readdirSync(dir, { withFileTypes: true })) {
+    const rel = prefix === '' ? entry.name : `${prefix}/${entry.name}`;
+    if (entry.isDirectory()) out.push(...filesUnder(path.join(dir, entry.name), rel));
+    else if (entry.isFile()) out.push(rel);
+  }
+  return out;
+};
+
+/** Byte-for-byte, not size or mtime: a one-byte edit keeping the length must be caught. */
+const differs = (a, b) => {
+  try {
+    if (!statSync(b).isFile()) return true;
+  } catch {
+    return true;
+  }
+  return !readFileSync(a).equals(readFileSync(b));
+};
+
+/** Every (skill, root, file) that is missing or different. */
+const drift = ({ packRoot, home, names }) => {
+  const found = [];
+  for (const name of names) {
+    const source = path.join(packRoot, 'skills', name);
+    let files;
+    try {
+      files = filesUnder(source);
+    } catch {
+      continue;
+    }
+    for (const root of SKILL_ROOTS) {
+      for (const rel of files) {
+        const from = path.join(source, ...rel.split('/'));
+        const to = path.join(home, root, 'skills', name, ...rel.split('/'));
+        if (differs(from, to)) found.push({ name, root, rel, from, to });
+      }
+    }
+  }
+  return found;
+};
+
+const resolve = (ctx = {}) => {
+  const packRoot = ctx.packRoot ?? packRootDefault();
+  return {
+    packRoot,
+    home: ctx.home ?? homeDir(),
+    detect: ctx.detectFullPack ?? detectFullPackDefault,
+    listSkillNames: ctx.listSkillNames ?? listSkillNamesDefault(packRoot),
+  };
+};
+
+export const checks = [
+  {
+    id: 'mini-skill-copies',
+    title: 'Skill copies in the home directory',
+    offers: ['copy-skills'],
+
+    async run(ctx = {}) {
+      const { packRoot, home, detect, listSkillNames } = resolve(ctx);
+
+      const full = detect({ home });
+      if (full.present) {
+        // Not a failure of this machine: on a full-pack box the copies are forbidden,
+        // so their absence is correct. mini-install-scope is what fails if they exist.
+        return {
+          status: 'skip',
+          summary: 'The full skill pack is installed here, so the mini never copies into the home directory',
+          detail: `Markers:\n${full.markers.join('\n')}`,
+        };
+      }
+
+      const names = listSkillNames();
+      if (names.length === 0) {
+        return { status: 'skip', summary: `No skills found under ${path.join(packRoot, 'skills')}` };
+      }
+
+      const missing = drift({ packRoot, home, names });
+      if (missing.length > 0) {
+        const where = [...new Set(missing.map((m) => `${m.name} → ${path.join(home, m.root, 'skills', m.name)}`))];
+        return {
+          status: 'fail',
+          summary: `${missing.length} file(s) are missing or differ across ${where.length} location(s)`,
+          detail: where.join('\n'),
+          actions: [{ kind: 'fix', fixId: 'copy-skills' }],
+        };
+      }
+      return { status: 'pass', summary: `${names.length} skill(s) match in both home directories` };
+    },
+
+    fixes: {
+      async 'copy-skills'(ctx = {}) {
+        const { packRoot, home, detect, listSkillNames } = resolve(ctx);
+
+        const full = detect({ home });
+        if (full.present) {
+          return {
+            status: 'refused',
+            summary: 'Refused: the full skill pack is installed here, and the mini never installs natively beside it',
+          };
+        }
+
+        const names = listSkillNames();
+        // Validate EVERY name before writing anything, so a hostile name cannot be
+        // preceded by partial writes from the safe ones.
+        const unsafe = names.filter((n) => !isSafeName(n));
+        if (unsafe.length > 0) {
+          return {
+            status: 'refused',
+            summary: `Refused: ${unsafe.map((n) => JSON.stringify(n)).join(', ')} is not a plain skill name`,
+          };
+        }
+
+        const pending = drift({ packRoot, home, names });
+        if (pending.length === 0) {
+          return { status: 'fixed', summary: 'Already up to date; 0 files written' };
+        }
+
+        for (const { from, to } of pending) {
+          if (!existsSync(from)) continue;
+          atomicWrite(to, readFileSync(from));
+        }
+        return { status: 'fixed', summary: `Copied ${pending.length} file(s) into the home skill directories` };
+      },
+    },
+  },
+];
diff --git a/lib/doctor/skills.test.mjs b/lib/doctor/skills.test.mjs
new file mode 100644
index 0000000..ae32fbd
--- /dev/null
+++ b/lib/doctor/skills.test.mjs
@@ -0,0 +1,187 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
+import path from 'node:path';
+import { tempDir } from '../platform/paths.mjs';
+import { outcomeConformance, fixOutcomeConformance } from './contract.mjs';
+import { checks } from './skills.mjs';
+
+const check = checks.find((c) => c.id === 'mini-skill-copies');
+assert.ok(check, 'mini-skill-copies must exist');
+
+const run = async (ctx) => {
+  const outcome = await check.run(ctx);
+  assert.deepEqual(outcomeConformance(outcome, check.id), [], JSON.stringify(outcome));
+  return outcome;
+};
+
+const fix = async (ctx) => {
+  const outcome = await check.fixes['copy-skills'](ctx);
+  assert.deepEqual(fixOutcomeConformance(outcome, 'copy-skills'), [], JSON.stringify(outcome));
+  return outcome;
+};
+
+/** A pack with `skills/<name>/SKILL.md`, and an empty home. */
+const world = (skills = { 'refine-ui': 'one' }) => {
+  const root = mkdtempSync(path.join(tempDir(), 'doctor-skills-'));
+  const packRoot = path.join(root, 'pack');
+  const home = path.join(root, 'home');
+  mkdirSync(home, { recursive: true });
+  for (const [name, body] of Object.entries(skills)) {
+    mkdirSync(path.join(packRoot, 'skills', name), { recursive: true });
+    writeFileSync(path.join(packRoot, 'skills', name, 'SKILL.md'), body);
+  }
+  return { root, packRoot, home, dispose: () => rmSync(root, { recursive: true, force: true }) };
+};
+
+const noFullPack = () => ({ present: false, markers: [] });
+const fullPack = () => ({ present: true, markers: ['~/.prometheus/setup-state.json'] });
+
+const copied = (home, root, name) => path.join(home, root, 'skills', name, 'SKILL.md');
+
+test('a home missing every copy fails, naming the skill and both locations', async () => {
+  const w = world();
+  try {
+    const outcome = await run({ packRoot: w.packRoot, home: w.home, detectFullPack: noFullPack });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.detail, /refine-ui/);
+    assert.match(outcome.detail, /\.agents/);
+    assert.match(outcome.detail, /\.claude/);
+    assert.deepEqual(outcome.actions, [{ kind: 'fix', fixId: 'copy-skills' }]);
+  } finally {
+    w.dispose();
+  }
+});
+
+test('the fix copies to both roots, and a second run passes', async () => {
+  const w = world();
+  try {
+    const ctx = { packRoot: w.packRoot, home: w.home, detectFullPack: noFullPack };
+
+    const applied = await fix(ctx);
+    assert.equal(applied.status, 'fixed');
+
+    assert.equal(readFileSync(copied(w.home, '.agents', 'refine-ui'), 'utf8'), 'one');
+    assert.equal(readFileSync(copied(w.home, '.claude', 'refine-ui'), 'utf8'), 'one');
+
+    assert.equal((await run(ctx)).status, 'pass');
+  } finally {
+    w.dispose();
+  }
+});
+
+test('a drifted copy is detected byte for byte and repaired', async () => {
+  const w = world();
+  try {
+    const ctx = { packRoot: w.packRoot, home: w.home, detectFullPack: noFullPack };
+    await fix(ctx);
+
+    // One byte different — same length, so a size comparison would miss it.
+    writeFileSync(copied(w.home, '.agents', 'refine-ui'), 'ONE');
+
+    const drifted = await run(ctx);
+    assert.equal(drifted.status, 'fail');
+    assert.match(drifted.detail, /refine-ui/);
+
+    assert.equal((await fix(ctx)).status, 'fixed');
+    assert.equal(readFileSync(copied(w.home, '.agents', 'refine-ui'), 'utf8'), 'one');
+    assert.equal((await run(ctx)).status, 'pass');
+  } finally {
+    w.dispose();
+  }
+});
+
+test('the fix is idempotent: re-applying writes nothing', async () => {
+  const w = world();
+  try {
+    const ctx = { packRoot: w.packRoot, home: w.home, detectFullPack: noFullPack };
+    await fix(ctx);
+
+    const again = await fix(ctx);
+    assert.equal(again.status, 'fixed');
+    assert.match(again.summary, /0|no|already|nothing/i);
+  } finally {
+    w.dispose();
+  }
+});
+
+// A-3. The fix writes under the user's home: the one real trust boundary in this change.
+test('a name that escapes the skills directory is refused, and nothing is written', async () => {
+  for (const hostile of ['../evil', 'a/../../evil', 'nested/deep', '..', '/absolute', 'C:\\windows']) {
+    const w = world({ 'refine-ui': 'one' });
+    try {
+      const ctx = {
+        packRoot: w.packRoot,
+        home: w.home,
+        detectFullPack: noFullPack,
+        // The hostile name arrives as if the pack listing produced it.
+        listSkillNames: () => [hostile],
+      };
+
+      const outcome = await fix(ctx);
+      assert.equal(outcome.status, 'refused', `${hostile} must be refused`);
+      assert.match(outcome.summary, /refus/i);
+
+      // Nothing at all may have been created under the home.
+      assert.deepEqual(readdirSync(w.home), [], `${hostile} wrote into the home`);
+    } finally {
+      w.dispose();
+    }
+  }
+});
+
+test('the fix never deletes a file the pack does not have', async () => {
+  const w = world();
+  try {
+    const ctx = { packRoot: w.packRoot, home: w.home, detectFullPack: noFullPack };
+    mkdirSync(path.join(w.home, '.claude', 'skills', 'someone-elses'), { recursive: true });
+    writeFileSync(path.join(w.home, '.claude', 'skills', 'someone-elses', 'SKILL.md'), 'theirs');
+
+    await fix(ctx);
+
+    assert.equal(readFileSync(path.join(w.home, '.claude', 'skills', 'someone-elses', 'SKILL.md'), 'utf8'), 'theirs');
+  } finally {
+    w.dispose();
+  }
+});
+
+// openspec/config.yaml, binding: never install natively beside the full pack.
+test('on a full-pack machine the check skips and the fix refuses, writing nothing', async () => {
+  const w = world();
+  try {
+    const ctx = { packRoot: w.packRoot, home: w.home, detectFullPack: fullPack };
+
+    const outcome = await run(ctx);
+    assert.equal(outcome.status, 'skip');
+    assert.match(outcome.summary + outcome.detail, /full (skill )?pack/i);
+    assert.equal(outcome.actions, undefined, 'a skipped check must not offer its fix');
+
+    const refused = await fix(ctx);
+    assert.equal(refused.status, 'refused');
+    assert.match(refused.summary, /full (skill )?pack/i);
+    assert.deepEqual(readdirSync(w.home), [], 'the fix wrote into the home beside a full pack');
+  } finally {
+    w.dispose();
+  }
+});
+
+test('copies are files, never symlinks', async () => {
+  const w = world();
+  try {
+    await fix({ packRoot: w.packRoot, home: w.home, detectFullPack: noFullPack });
+
+    const { lstatSync } = await import('node:fs');
+    assert.equal(lstatSync(copied(w.home, '.agents', 'refine-ui')).isSymbolicLink(), false);
+    assert.equal(lstatSync(copied(w.home, '.claude', 'refine-ui')).isSymbolicLink(), false);
+  } finally {
+    w.dispose();
+  }
+});
+
+test('the check satisfies the contract statically and offers exactly its one fix', async () => {
+  const { checkConformance } = await import('./contract.mjs');
+
+  assert.deepEqual(checkConformance(check), []);
+  assert.deepEqual(check.offers, ['copy-skills']);
+});
