+++ b/lib/doctor/tools.test.mjs
@@ -0,0 +1,112 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
+import path from 'node:path';
+import { tempDir } from '../platform/paths.mjs';
+import { outcomeConformance, checkConformance } from './contract.mjs';
+import { checks } from './tools.mjs';
+
+const byId = (id) => {
+  const check = checks.find((c) => c.id === id);
+  assert.ok(check, `no check ${id}`);
+  return check;
+};
+
+const run = async (id, ctx) => {
+  const outcome = await byId(id).run(ctx);
+  assert.deepEqual(outcomeConformance(outcome, id), [], JSON.stringify(outcome));
+  return outcome;
+};
+
+const found = (stdout) => () => ({ status: 0, stdout, stderr: '' });
+const missing = () => () => ({ status: 1, stdout: '', stderr: 'command not found' });
+
+test('mini-pk passes and names the version', async () => {
+  const outcome = await run('mini-pk', { spawn: found('pk 1.9.0\n') });
+
+  assert.equal(outcome.status, 'pass');
+  assert.match(outcome.summary, /1\.9\.0/);
+});
+
+// pk is optional: the Karpathy flow degrades without it. Absent is a warning.
+test('mini-pk warns when the binary is absent', async () => {
+  const outcome = await run('mini-pk', { spawn: missing() });
+
+  assert.equal(outcome.status, 'warn');
+  assert.match(outcome.summary + outcome.detail, /pk/);
+});
+
+// Present but broken is a real fault: the binary exists and cannot answer.
+test('mini-pk fails when the binary is present but errors', async () => {
+  const outcome = await run('mini-pk', {
+    spawn: () => ({ status: 101, stdout: '', stderr: 'illegal instruction' }),
+    // A resolver that says the binary IS there distinguishes broken from absent.
+    resolve: () => '/usr/local/bin/pk',
+  });
+
+  assert.equal(outcome.status, 'fail');
+  assert.match(outcome.summary + outcome.detail, /101|illegal/i);
+});
+
+test('the pk probe never runs through a shell', async () => {
+  const calls = [];
+  await run('mini-pk', {
+    spawn: (file, args) => {
+      calls.push([file, ...args]);
+      return { status: 0, stdout: 'pk 1.9.0\n', stderr: '' };
+    },
+  });
+
+  assert.equal(calls.length, 1);
+  assert.ok(!calls[0].some((a) => typeof a === 'string' && /[;&|]/.test(a)), JSON.stringify(calls));
+});
+
+test('mini-sycophancy-correction warns when the binary cannot be resolved', async () => {
+  const outcome = await run('mini-sycophancy-correction', { resolve: () => null });
+
+  assert.equal(outcome.status, 'warn');
+  assert.match(outcome.summary + outcome.detail, /sycophancy/i);
+});
+
+test('mini-sycophancy-correction passes when resolved with the expected gateway', async () => {
+  const dir = mkdtempSync(path.join(tempDir(), 'doctor-syco-'));
+  try {
+    mkdirSync(path.join(dir, 'cfg'), { recursive: true });
+    const skillToml = path.join(dir, 'cfg', 'skill.toml');
+    writeFileSync(skillToml, 'gateway = "http://localhost:4000/v1"\n');
+
+    const outcome = await run('mini-sycophancy-correction', {
+      resolve: () => path.join(dir, 'sycophancy'),
+      skillToml: () => skillToml,
+    });
+
+    assert.equal(outcome.status, 'pass');
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
+
+// The gateway is fixed at :4000/v1 by project rule. A skill.toml naming another one
+// would silently send review traffic somewhere else, so it is a failure, not a warning.
+test('mini-sycophancy-correction fails when skill.toml names another gateway', async () => {
+  const dir = mkdtempSync(path.join(tempDir(), 'doctor-syco-'));
+  try {
+    const skillToml = path.join(dir, 'skill.toml');
+    writeFileSync(skillToml, 'gateway = "https://api.example.com/v1"\n');
+
+    const outcome = await run('mini-sycophancy-correction', {
+      resolve: () => path.join(dir, 'sycophancy'),
+      skillToml: () => skillToml,
+    });
+
+    assert.equal(outcome.status, 'fail');
+    assert.match(outcome.summary + outcome.detail, /api\.example\.com/);
+    assert.match(outcome.summary + outcome.detail, /4000/);
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
+
+test('every check in this group satisfies the contract statically', () => {
+  for (const check of checks) assert.deepEqual(checkConformance(check), [], check.id);
+});
diff --git a/lib/platform/full-pack.mjs b/lib/platform/full-pack.mjs
new file mode 100644
index 0000000..0bd0d11
--- /dev/null
+++ b/lib/platform/full-pack.mjs
@@ -0,0 +1,94 @@
+// Detects a NATIVE full-pack install (prometheus-skill-pack / the full skill system).
+//
+// openspec/config.yaml, binding: the mini pack is never installed natively on a machine
+// that already has the full pack. Inside the-boss's own data directory is fine; anywhere
+// under the user's home on such a machine is not, because the two would shadow each
+// other's skills. This module is how that rule is enforced mechanically.
+//
+// Read-only by construction: it decides whether we may write, so it must never write.
+// Every effect is injected, so the tests run on a machine in any state.
+
+import { existsSync, readdirSync, statSync } from 'node:fs';
+import path from 'node:path';
+import { homeDir } from './paths.mjs';
+import { spawnExecutable } from './spawn.mjs';
+
+const SKILL_ROOTS = ['.claude', '.agents'];
+const FULL_PACK_SKILL = 'kbd-process-orchestrator';
+const UNIT_PREFIX = 'ai.prometheus.';
+
+const isDirectory = (p) => {
+  try {
+    return statSync(p).isDirectory();
+  } catch {
+    return false;
+  }
+};
+
+/**
+ * Which markers of a native full-pack install are present.
+ *
+ * @param {object} [options]
+ * @param {string} [options.home] the home directory to inspect; defaults to the real one
+ * @param {Function} [options.spawn] `(file, args) => { status, stdout, stderr }`
+ * @param {string} [options.platform] `process.platform`, for the service-unit marker
+ * @returns {{ present: boolean, markers: string[] }} every marker found, each naming itself
+ */
+export function detectFullPack({ home = homeDir(), spawn = spawnExecutable, platform = process.platform } = {}) {
+  // An unreadable home is NOT "absent". Returning absent here would report a full-pack
+  // machine as clean and let the installer write into it — the rule failing open on
+  // exactly the side that does damage.
+  if (!isDirectory(home)) {
+    throw new Error(`detectFullPack: home ${JSON.stringify(home)} is not a readable directory`);
+  }
+
+  const markers = [];
+
+  // The CLI on PATH. `where` on Windows, `command -v` is a shell builtin so it cannot be
+  // spawned without a shell — `which` is the portable executable everywhere else.
+  const probe = platform === 'win32' ? 'where' : 'which';
+  const onPath = spawn(probe, ['prometheus']);
+  if (onPath?.status === 0 && String(onPath.stdout ?? '').trim() !== '') {
+    markers.push(`the prometheus CLI is on PATH (${String(onPath.stdout).trim().split(/\r?\n/)[0]})`);
+  }
+
+  const setupState = path.join(home, '.prometheus', 'setup-state.json');
+  if (existsSync(setupState)) {
+    markers.push(`the full pack's setup-state.json exists (${setupState})`);
+  }
+
+  for (const root of SKILL_ROOTS) {
+    const skill = path.join(home, root, 'skills', FULL_PACK_SKILL);
+    if (isDirectory(skill)) {
+      markers.push(`the full pack's ${FULL_PACK_SKILL} skill is installed (${skill})`);
+    }
+  }
+
+  // Service units. The full pack installs LaunchAgents on macOS and systemd user units on
+  // Linux, both named `ai.prometheus.*` (verified on a full-pack machine: nine of them in
+  // ~/Library/LaunchAgents). Windows has no equivalent the pack installs, so there is
+  // nothing to look for there. A missing directory is simply no marker — unlike `home`,
+  // its absence is the ordinary case on a clean machine, not a failure to look.
+  const unitDir =
+    platform === 'darwin'
+      ? path.join(home, 'Library', 'LaunchAgents')
+      : platform === 'win32'
+        ? null
+        : path.join(home, '.config', 'systemd', 'user');
+
+  if (unitDir !== null && isDirectory(unitDir)) {
+    let units = [];
+    try {
+      units = readdirSync(unitDir).filter((name) => name.startsWith(UNIT_PREFIX));
+    } catch {
+      units = [];
+    }
+    if (units.length > 0) {
+      const shown = units.slice(0, 3).join(', ');
+      const rest = units.length > 3 ? `, and ${units.length - 3} more` : '';
+      markers.push(`the full pack's service units are installed in ${unitDir} (${shown}${rest})`);
+    }
+  }
+
+  return { present: markers.length > 0, markers };
+}
